WITH base AS (SELECT id, store_id, sale_date, units, revenue, GREATEST(revenue, units) greatest_revenue_units FROM store_sales WHERE product_id IN (5, 10)) SELECT id, greatest_revenue_units, LAG(units) OVER w_ordered prev_units, LEAD(greatest_revenue_units) OVER w_ordered next_greatest_revenue_units, ROW_NUMBER() OVER w_ordered event_seq, CUME_DIST() OVER (PARTITION BY store_id ORDER BY greatest_revenue_units DESC) greatest_revenue_units_cume_dist FROM base WINDOW w_ordered AS (PARTITION BY store_id ORDER BY greatest_revenue_units, id);
